        inset: calc(var(--bubble-size) / 1.5) 0 auto auto;
      }
    }
  }

  /* Child items
  /* ------------------------------------------------------------------------ */

  .card-perma__bg {
    background-color: var(--color-container);
    border-radius: 0.2em;
